'use strict';

var escape = require('../helpers/escape');

function _render(context, options) {

	var $ = context.jQuery,
		PubSub = context.PubSub;

	//Create the question
	var question = options.question ? options.question : 'textarea',
		name = options.name ? options.name : question,
		attrib = escape.htmlAttributeEscape(JSON.stringify(options), { singleQuotes: true });

	//HTML
	var $html = $(
		'<div class="form-group">' +
			'<h3>' + question + '</h3>' +
			'<textarea class="form-control f3-textarea" name="' + name + '" data-options=\'' + attrib + '\'>' +
			'</textarea>' +
		'</div>');

	//Bind change
	$html.find('textarea').on('change', function(){

		//Publish the event
		PubSub.publish('f3.textarea', {
			'trigger': this,
			'event': 'change'
		});

	}).on('click', function(){

		//Publish the event
		PubSub.publish('f3.textarea', {
			'trigger': this,
			'event': 'click'
		});

	});

	return $html;

}

function _read(options, value) {

	return {
		question: options.question || 'textarea',
		name: options.name || options.question,

		text: value,
		value: value
	};

}

module.exports = {
	render: _render,
	read: _read,
	name: 'textarea'
};
